<?php $id=(int)($_GET['id']??0); $r=mysqli_fetch_assoc(mysqli_query($koneksi,"SELECT * FROM kategori WHERE idkategori=$id")); ?><h2>Edit Kategori</h2><form action="proses/proseskategori.php?aksi=edit" method="post" enctype="multipart/form-data"><input type="hidden" name="idkategori" value="<?=$r['idkategori']?>"><div class="form-group"><label>Nama Kategori</label><input class="form-control" name="namakategori" value="<?=htmlspecialchars($r['namakategori'])?>" required></div><div class="form-group"><label>Gambar Kategori</label><?php if(!empty($r['foto'])): ?><div class="mb-2"><img src="assets/uploads/kategori/<?=htmlspecialchars($r['foto'])?>" alt="Gambar kategori" style="width:110px;height:85px;object-fit:cover;border-radius:8px"></div><?php endif; ?><input class="form-control-file" type="file" name="foto" accept="image/jpeg,image/png,image/webp"><small class="text-muted">Kosongkan jika tidak ingin mengganti gambar.</small></div><button class="btn btn-primary">Simpan</button></form>